import * as React from "react";
import { cx } from "./cx";
import type { SelectOption } from "./select";

export interface ComboboxProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  options: SelectOption[];
  value?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  emptyLabel?: React.ReactNode;
}

/** Filtered listbox on the quiet field. */
export function Combobox({
  options,
  value,
  onValueChange,
  placeholder = "Search…",
  emptyLabel = "Nothing found.",
  className,
  ...props
}: ComboboxProps) {
  const idBase = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const [activeIndex, setActiveIndex] = React.useState(0);

  const selected = options.find((o) => o.value === value);
  const matches = options.filter((o) =>
    String(o.label).toLowerCase().includes(query.toLowerCase()),
  );

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const pick = (option: SelectOption) => {
    onValueChange?.(option.value);
    setQuery("");
    setOpen(false);
  };

  return (
    <div ref={rootRef} className={cx("rs-combobox", className)} {...props}>
      <input
        className="rs-input rs-input-full"
        role="combobox"
        aria-expanded={open}
        aria-controls={`${idBase}-listbox`}
        aria-autocomplete="list"
        placeholder={placeholder}
        value={open ? query : String(selected?.label ?? "")}
        onFocus={() => {
          setQuery("");
          setActiveIndex(0);
          setOpen(true);
        }}
        onChange={(e) => {
          setQuery(e.target.value);
          setActiveIndex(0);
          setOpen(true);
        }}
        onKeyDown={(e) => {
          if (!open) return;
          if (e.key === "Escape") setOpen(false);
          if (e.key === "ArrowDown") {
            e.preventDefault();
            setActiveIndex((i) => Math.min(matches.length - 1, i + 1));
          }
          if (e.key === "ArrowUp") {
            e.preventDefault();
            setActiveIndex((i) => Math.max(0, i - 1));
          }
          if (e.key === "Enter") {
            e.preventDefault();
            const match = matches[activeIndex];
            if (match) pick(match);
          }
        }}
      />
      {open && (
        <div id={`${idBase}-listbox`} role="listbox" className="rs-menu">
          {matches.length === 0 && <div className="rs-combobox-empty">{emptyLabel}</div>}
          {matches.map((option, index) => (
            <button
              key={option.value}
              type="button"
              role="option"
              aria-selected={option.value === value}
              className={cx("rs-menu-item", index === activeIndex && "rs-menu-item-active")}
              onPointerEnter={() => setActiveIndex(index)}
              onClick={() => pick(option)}
            >
              {option.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";
import { Icon } from "./icon";

export interface SelectOption {
  value: string;
  label: React.ReactNode;
}

export interface SelectProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  placeholder?: React.ReactNode;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
}

/** Listbox on a hairline trigger; the open menu overlays. */
export function Select({
  options,
  value,
  defaultValue,
  placeholder = "Select…",
  onValueChange,
  disabled,
  className,
  ...props
}: SelectProps) {
  const idBase = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [open, setOpen] = React.useState(false);
  const [inner, setInner] = React.useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const selectedIndex = options.findIndex((o) => o.value === current);
  const [activeIndex, setActiveIndex] = React.useState(Math.max(0, selectedIndex));

  const select = (next: string) => {
    if (!isControlled) setInner(next);
    onValueChange?.(next);
    setOpen(false);
    triggerRef.current?.focus();
  };

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const onTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key) && !open) {
      e.preventDefault();
      setActiveIndex(Math.max(0, selectedIndex));
      setOpen(true);
      return;
    }
    if (!open) return;
    if (e.key === "Escape") setOpen(false);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(options.length - 1, i + 1));
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    }
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const active = options[activeIndex];
      if (active) select(active.value);
    }
  };

  const selected = selectedIndex >= 0 ? options[selectedIndex] : undefined;

  return (
    <div ref={rootRef} className={cx("rs-select", className)} {...props}>
      <button
        ref={triggerRef}
        type="button"
        className="rs-dropdown"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${idBase}-listbox`}
        disabled={disabled}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={onTriggerKeyDown}
      >
        <span>{selected ? selected.label : placeholder}</span>
        <Icon name="chevron-right" rotate={90} />
      </button>
      {open && (
        <div id={`${idBase}-listbox`} role="listbox" className="rs-menu" aria-activedescendant={`${idBase}-opt-${activeIndex}`}>
          {options.map((option, index) => (
            <button
              key={option.value}
              id={`${idBase}-opt-${index}`}
              type="button"
              role="option"
              aria-selected={option.value === current}
              className={cx(
                "rs-menu-item",
                (option.value === current || index === activeIndex) && "rs-menu-item-active",
              )}
              onPointerEnter={() => setActiveIndex(index)}
              onClick={() => select(option.value)}
            >
              {option.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";
import {
  iconGroups,
  iconLabel,
  iconNames,
  marks,
  resolveIcon,
  type IconName,
  type IconRotate,
  type MarkEl,
} from "./icon-marks";

export { iconGroups, iconLabel, iconNames, resolveIcon };
export type { IconName, IconRotate };
export type { DrawnName, IconAlias, IconGroup } from "./icon-marks";

/**
 * Raster chrome marks. Vera 28 Aug 2026.
 *
 * 16×16 module, optical center 8,8. Stroke 1, currentColor, fill none.
 * Cap butt, join miter, no rx. Hairline stays 1 CSS px at 12 and 16.
 * Copied is check. Accordion down is chevron-right rotated 90°.
 */
export const ICON_STROKE = 1;
export const ICON_VIEWBOX = 16;

export const iconInk = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: ICON_STROKE,
  strokeLinecap: "butt",
  strokeLinejoin: "miter",
  vectorEffect: "non-scaling-stroke",
} as const;

export type IconSize = 12 | 16;

function renderEl(el: MarkEl, key: number): React.ReactNode {
  switch (el.t) {
    case "path":
      return <path key={key} d={el.d} {...iconInk} />;
    case "rect":
      return <rect key={key} x={el.x} y={el.y} width={el.w} height={el.h} {...iconInk} />;
    case "circle":
      return <circle key={key} cx={el.cx} cy={el.cy} r={el.r} {...iconInk} />;
    case "line":
      return <line key={key} x1={el.x1} y1={el.y1} x2={el.x2} y2={el.y2} {...iconInk} />;
  }
}

export interface IconProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children" | "rotate"> {
  name: IconName;
  size?: IconSize;
  /** Same mark, spun around 8,8. Accordion down is chevron-right at 90. */
  rotate?: IconRotate;
}

/** One mark. Size is the drawn square; the viewBox is always 16. */
export function Icon({ name, size = 16, rotate, className, ...props }: IconProps) {
  const resolved = resolveIcon(name);
  const turn = rotate ?? resolved.rotate;
  const nodes = marks[resolved.mark].map(renderEl);
  return (
    <svg
      className={cx("rs-icon", className)}
      viewBox="0 0 16 16"
      width={size}
      height={size}
      aria-hidden="true"
      {...iconInk}
      {...props}
    >
      {turn ? <g transform={`rotate(${turn} 8 8)`}>{nodes}</g> : nodes}
    </svg>
  );
}

/** Full family at 12 and 16, grouped. */
export function IconCatalog({ className }: { className?: string }) {
  return (
    <div className={cx("rs-icon-catalog", className)}>
      {iconGroups.map((group) => (
        <section key={group.title} className="rs-icon-group">
          <h3 className="rs-icon-group-title">{group.title}</h3>
          <div className="rs-icon-grid">
            {group.names.map((mark) => (
              <div key={`${group.title}-${mark}`} className="rs-icon-cell">
                <div className="rs-icon-pair">
                  <Icon name={mark} size={12} />
                  <Icon name={mark} size={16} />
                </div>
                <span className="rs-icon-label">{iconLabel(mark)}</span>
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Combobox: the quiet field with a filtered overlay ── */
.rs-combobox{position:relative;display:inline-block;min-width:200px}
.rs-combobox .rs-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px;max-height:240px;overflow-y:auto}
.rs-combobox-empty{padding:10px 12px;font-size:13px;letter-spacing:-.01em;color:var(--text-secondary)}
